"""Bind a reviewed Native packet to original source bytes before live construction."""
from __future__ import annotations

import hashlib
from pathlib import Path

REQUIRED = {"map", "highway", "centerline", "lane_forward", "lane_reverse",
            "ego_vehicle", "overtaken_vehicle", "camera_plan"}


def bind(packet, root):
    root = Path(root).resolve()
    entries = packet.get("sources")
    if not isinstance(entries, list):
        raise ValueError("reviewed original source inventory missing")
    roles = [entry.get("role") for entry in entries if isinstance(entry, dict)]
    if len(roles) != len(set(roles)) or not REQUIRED <= set(roles):
        raise ValueError("reviewed source roles missing or duplicated")
    if "oncoming" in packet.get("actors", {}) and "oncoming_vehicle" not in roles:
        raise ValueError("oncoming original source missing")
    if packet.get("case_id", "").endswith("occluded_left") and "opaque_blocker" not in roles:
        raise ValueError("opaque blocker original source missing")
    bound = {}
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("path") or not entry.get("sha256"):
            raise ValueError("unversioned reviewed source entry")
        candidate = root / entry["path"]
        if candidate.is_symlink() or not candidate.is_file() or not candidate.resolve().is_relative_to(root):
            raise ValueError("reviewed original source path missing or escapes root")
        actual = hashlib.sha256(candidate.read_bytes()).hexdigest()
        if actual != entry["sha256"]:
            raise ValueError("reviewed original source bytes changed")
        bound[entry["role"]] = {"path": str(candidate), "sha256": actual}
    if bound["map"]["sha256"] != packet.get("map_opendrive_sha256"):
        raise ValueError("reviewed map source hash differs from Native setup")
    if bound["centerline"]["sha256"] != packet.get("road", {}).get("centerline_source_sha256"):
        raise ValueError("reviewed centerline source hash differs from Native setup")
    return bound

"""Saved-only NRS 484B.213(1) descriptive finalizer.

Reads sealed original sources; never drives CARLA or decides legal judgments.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from pass_measure import measure

SOURCES = ("pass-history.jsonl", "road-context.json", "native-result.json",
           "video_frames.jsonl", "reviewed-sources/map.source",
           "reviewed-sources/centerline.source")


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def required(root, name):
    path = Path(root) / name
    if not path.is_file():
        raise ValueError("Missing required source: " + name)
    return path


def rows(path):
    return [json.loads(s) for s in Path(path).read_text().splitlines() if s.strip()]


def measure_actor_scope(data):
    return {"ego_vehicle": True, "overtaken_vehicle": True,
            "oncoming_present": any("oncoming" in f["actors"] for f in data["frames"])}


def measure_highway_geometry(data):
    road = data["road"]
    return {"public_highway": road["public_highway"], "lane_count": road["lane_count"],
            "opposite_permitted_directions": road["opposite_permitted_directions"],
            "undivided": road["undivided"], "centerline_source": road["centerline_source"]}


def measure_left_pass(data):
    return {"left_of_center_frames": data["result"]["left_of_center_frames"],
            "ego_and_target_history_frames": data["result"]["original_frame_count"]}


def measure_visibility(data):
    samples = data["result"]["per_frame"]
    return {"clear_distance_m": [s["left_ray_clear_distance_min_m"] for s in samples],
            "opaque_hit_frames": [s["original_frame"] for s in samples if s["left_ray_any_occluded"]],
            "proxy": "incoming-lane virtual observer rays; not driver perception"}


def measure_oncoming(data):
    return {"forward_station_gap_m": [s["oncoming_forward_station_gap_m"]
                                      for s in data["result"]["per_frame"]],
            "judgment": "unresolved"}


def measure_completion(data):
    return {"pass_and_return_frame": data["result"]["measured_pass_and_return_frame"],
            "left_of_center_frames": data["result"]["left_of_center_frames"]}


def measure_opposite_response(data):
    return {"original_response_history": [s["oncoming_response"]
                                          for s in data["result"]["per_frame"]],
            "interference_judgment": "unresolved"}


def measure_overtaken_response(data):
    return {"original_speed_history_mps": [s["overtaken_speed_mps"]
                                           for s in data["result"]["per_frame"]],
            "interference_judgment": "unresolved"}


METHODS = (measure_actor_scope, measure_highway_geometry, measure_left_pass,
           measure_visibility, measure_oncoming, measure_completion,
           measure_opposite_response, measure_overtaken_response)


def analyze(root):
    root = Path(root)
    for name in SOURCES:
        required(root, name)
    history = rows(root / "pass-history.jsonl")
    mapping = rows(root / "video_frames.jsonl")
    if len(history) != len(mapping) or not history:
        raise ValueError("original history/frame-map join incomplete")
    for index, (body, frame) in enumerate(zip(history, mapping)):
        if body.get("original_frame") != index or body.get("carla_frame") != frame.get("carla_frame") or abs(body.get("time_s", -1)-frame.get("time_s", -2)) > 1e-6:
            raise ValueError("original body/frame-map identity mismatch")
    road = json.loads((root / "road-context.json").read_text())
    native = json.loads((root / "native-result.json").read_text())
    config = json.loads(required(root, "config.json").read_text())
    if native.get("recording_description") != config.get("case", {}).get("recording_description"):
        raise ValueError("original recording description differs from selected case")
    fixture_path = root / "fixture-provenance.json"
    is_fixture = fixture_path.is_file() and json.loads(fixture_path.read_text()).get("diagnostic_fixture") is True
    if not is_fixture and len(history) != config.get("duration_s", len(history))*20:
        raise ValueError("original episode duration incomplete")
    source_hashes = {name: sha(root / name) for name in SOURCES}
    if road.get("centerline_source_sha256") != source_hashes["reviewed-sources/centerline.source"]:
        raise ValueError("original centerline source bytes changed")
    road["centerline_source"] = source_hashes["reviewed-sources/centerline.source"]
    packet = {"format": "nrs-484b-213-1-native-projection",
              "source": {"native_result_sha256": source_hashes["native-result.json"],
                         "map_sha256": source_hashes["reviewed-sources/map.source"],
                         "frame_map_sha256": source_hashes["video_frames.jsonl"]},
              "road": road,
              "frames": [dict(row, ray_source_sha256=source_hashes["pass-history.jsonl"])
                         for row in history]}
    result = measure(packet)
    data = {"result": result, "road": road, "frames": history}
    measurements = {}
    for method in METHODS:
        name = method.__name__
        measurements[name] = {"value": method(data), "method": name,
                              "sources": dict(source_hashes)}
    report = {"format": "worker-analysis-report", "case_id": config["selected_case_id"],
              "measurements": measurements, "analysis_complete": True,
              "physical_acceptance_claimed": False,
              "limitations": ["Actual pixels and physical completion require independent local review.",
                              "Qualitative statutory judgments remain unresolved."]}
    return report, native


def channel_value(name, row, road):
    actors = row["actors"]
    ego, target = actors["ego"], actors["overtaken"]
    oncoming = actors.get("oncoming")
    if name == "highway_geometry":
        return {key: road[key] for key in
                ("public_highway", "lane_count", "opposite_permitted_directions", "undivided")}
    if name == "centerline_and_lane_directions":
        return {"centerline_source_sha256": road["centerline_source_sha256"],
                "lanes": road["lanes"]}
    if name == "driver_and_vehicle_identity":
        return {"ego_actor_id": ego["actor_id"], "overtaken_actor_id": target["actor_id"],
                "oncoming_actor_id": oncoming["actor_id"] if oncoming else "absent"}
    if name == "ego_target_oncoming_body_history":
        return actors
    if name == "pass_completion":
        return {"ego_left_body_edge_m": ego["centerline_signed_body_edge_m"],
                "ego_rear_station_m": ego["rear_station_m"],
                "overtaken_front_station_m": target["front_station_m"]}
    if name == "left_side_visibility":
        return row["left_side_rays"]
    if name == "oncoming_forward_distance":
        return {"present": bool(oncoming),
                "forward_station_gap_m": oncoming["station_m"]-ego["station_m"] if oncoming else "absent"}
    if name == "oncoming_start_gap_m":
        if oncoming is None:
            raise ValueError("oncoming gap channel requires original opposite-direction vehicle")
        return oncoming["station_m"]-ego["station_m"]
    if name == "opposite_vehicle_response":
        return {"present": bool(oncoming), "speed_mps": oncoming["speed_mps"] if oncoming else "absent",
                "lateral_m": oncoming["lateral_m"] if oncoming else "absent"}
    if name == "overtaken_vehicle_response":
        return {"speed_mps": target["speed_mps"], "lateral_m": target["lateral_m"]}
    if name == "original_frame_and_camera_join":
        return {"original_frame": row["original_frame"], "carla_frame": row["carla_frame"]}
    raise ValueError("unknown selected recording channel: " + name)


def write_channels(root, description):
    root = Path(root)
    history = rows(root / "pass-history.jsonl")
    road = json.loads((root / "road-context.json").read_text())
    folder = root / "channels"
    folder.mkdir(exist_ok=True)
    evidence = []
    for channel in description["channels"]:
        name = channel["name"]
        path = folder / (name + ".jsonl")
        if path.exists():
            raise ValueError("derived channel already exists")
        with path.open("x") as stream:
            for row in history:
                stream.write(json.dumps({"time_s": row["time_s"],
                                         "value": channel_value(name, row, road)},
                                        allow_nan=False) + "\n")
        evidence.append({"name": name, "unit": channel["unit"],
                         "reference": str(path.relative_to(root)),
                         "source_sha256": sha(path)})
    return evidence


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    report, native = analyze(args.attempt)
    from worker_exchange.native_output import physical_result, validate_result
    native["case_id"] = report["case_id"]
    native["measured_values"].update({key: item["value"] for key, item in report["measurements"].items()})
    native["recording_evidence"] = write_channels(args.attempt, native["recording_description"])
    native = physical_result(args.attempt, native)
    if any(c["name"] == "oncoming_start_gap_m" for c in native["recording_description"]["channels"]):
        observed = rows(args.attempt / "channels/oncoming_start_gap_m.jsonl")
        native["realized_observables"]["oncoming_start_gap_m"] = {
            "value": observed[0]["value"], "unit": "m",
            "method": "Original source-bound forward station gap samples; retain full history",
            "time_window": "first original frame of selected passing episode",
            "statistic": "first", "sample_window_s": [observed[0]["time_s"], observed[0]["time_s"]],
            "reference": "channels/oncoming_start_gap_m.jsonl"}
    validate_result(native)
    (args.attempt / "result.json").write_text(json.dumps(native, indent=2) + "\n")
    args.output.write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()

"""Independent source-bound comparison of two saved measurement reports.

This checks physical measurement isolation. It does not resolve NRS judgment phrases.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

FACTORS = {
    "visibility_clear_vs_occluded": ("left_ray_any_occluded",),
    "oncoming_far_vs_near": ("oncoming_forward_station_gap_m",),
    "approaching_response": ("oncoming_response",),
    "overtaken_response": ("overtaken_speed_mps",),
    "passing_completion": ("measured_pass_and_return_frame",),
}


def _digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit(plan, left, right, left_path, right_path, comparison_id):
    matches = [c for c in plan["comparisons"] if c["comparison_id"] == comparison_id]
    if len(matches) != 1:
        raise ValueError("unknown comparison")
    comparison = matches[0]
    if [left.get("case_id"), right.get("case_id")] != comparison["case_ids"]:
        raise ValueError("case identity or order mismatch")
    for report in (left, right):
        if report.get("format") != "nrs-484b-213-1-comparison-input":
            raise ValueError("wrong saved comparison input")
        if not report.get("native_result_sha256") or not report.get("measurement_sha256"):
            raise ValueError("missing original source bindings")
        if not report.get("physical_completion_reviewed"):
            raise ValueError("physical completion not reviewed")
        if not report.get("full_video_decode_reviewed"):
            raise ValueError("full original video decode not reviewed")
        if not report.get("actual_pixels_reviewed"):
            raise ValueError("actual pixels not reviewed")
        if not isinstance(report.get("fixed_conditions"), dict) or not report["fixed_conditions"]:
            raise ValueError("missing measured fixed conditions")
        if not isinstance(report.get("measured_differences"), dict):
            raise ValueError("missing measured differences")
    if left["fixed_conditions"] != right["fixed_conditions"]:
        raise ValueError("fixed conditions differ")
    factors = FACTORS[comparison_id]
    for factor in factors:
        if factor not in left["measured_differences"] or factor not in right["measured_differences"]:
            raise ValueError("missing declared difference measurement")
        if left["measured_differences"][factor] == right["measured_differences"][factor]:
            raise ValueError("declared difference not measured")
    return {"format": "worker-comparison-audit-draft", "comparison_id": comparison_id,
            "case_ids": comparison["case_ids"], "left_report_sha256": _digest(left_path),
            "right_report_sha256": _digest(right_path), "checked_fixed_conditions": sorted(left["fixed_conditions"]),
            "checked_differences": list(factors), "judgment": "unresolved"}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--plan", type=Path, required=True)
    parser.add_argument("--left", type=Path, required=True)
    parser.add_argument("--right", type=Path, required=True)
    parser.add_argument("--comparison", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    result = audit(json.loads(args.plan.read_text()), json.loads(args.left.read_text()),
                   json.loads(args.right.read_text()), args.left, args.right,
                   args.comparison)
    args.output.write_text(json.dumps(result, indent=2) + "\n")


if __name__ == "__main__":
    main()

"""Independent original-source delivery audit for one exact passing episode.

A diagnostic protocol check verifies software joins only. Native acceptance requires
separate original pixel and physical review; no legal judgment is produced.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from native_scene import ASSIGNMENT, CASE_VARIANTS, CAMERAS


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def audit(attempt, case_id, output, *, diagnostic_protocol=False):
    from worker_exchange.media import audit as decode
    attempt, output = Path(attempt).resolve(), Path(output).resolve()
    if output.exists():
        raise ValueError("retain prior delivery audit output")
    if not case_id.startswith(ASSIGNMENT + "__") or case_id.removeprefix(ASSIGNMENT + "__") not in CASE_VARIANTS:
        raise ValueError("exact delivery case mismatch")
    required = ("pass-history.jsonl", "video_frames.jsonl", "trace.jsonl",
                "road-context.json", "native-result.json", "analysis-report.json", "result.json")
    for name in required:
        if not (attempt / name).is_file():
            raise ValueError("missing original delivery evidence: " + name)
    provenance = read(attempt / "acquisition-provenance.json")
    is_fixture = provenance.get("diagnostic_fixture") is True
    if diagnostic_protocol:
        if not is_fixture:
            raise ValueError("diagnostic protocol requires explicit synthetic provenance")
    elif is_fixture:
        raise ValueError("synthetic fixture cannot be accepted as Native delivery")
    else:
        seal = read(attempt / "capture-seal.json")
        if seal.get("events") != ["capture_finished", "encoders_closed", "restoration_verified"]:
            raise ValueError("Native closure order missing")
        for name, expected in seal.get("sources", {}).items():
            if sha(attempt / name) != expected:
                raise ValueError("sealed original source changed: " + name)
        native_exit = read(attempt / "native-exit.json")
        if native_exit.get("capture_seal_sha256") != sha(attempt / "capture-seal.json"):
            raise ValueError("Native exit source binding changed")
        owner = read(attempt / "owner-release-attested.json")
        if owner.get("event") != "owner_released" or owner.get("operator_attested") is not True:
            raise ValueError("operator owner release missing")
    history = rows(attempt / "pass-history.jsonl")
    mapping = rows(attempt / "video_frames.jsonl")
    trace = rows(attempt / "trace.jsonl")
    if not history or len(history) != len(mapping) or len(history) != len(trace):
        raise ValueError("original body/trace/frame count mismatch")
    for index, (body, frame, point) in enumerate(zip(history, mapping, trace)):
        if body.get("original_frame") != index or body.get("carla_frame") != frame.get("carla_frame") or point.get("frame") != frame.get("carla_frame") or abs(body.get("time_s", -1)-frame.get("time_s", -2)) > 1e-6:
            raise ValueError("original time join mismatch")
        if not {"ego", "overtaken"} <= set(body.get("actors", {})):
            raise ValueError("required passing participants absent")
        if case_id.endswith(("oncoming_close", "oncoming_distant", "opposite_response")) and "oncoming" not in body["actors"]:
            raise ValueError("required approaching vehicle absent")
    report = read(attempt / "analysis-report.json")
    result = read(attempt / "result.json")
    if report.get("case_id") != case_id or result.get("case_id") != case_id or not report.get("analysis_complete"):
        raise ValueError("saved analysis identity or completion missing")
    for value in report.get("measurements", {}).values():
        for name, expected in value.get("sources", {}).items():
            if sha(attempt / name) != expected:
                raise ValueError("source-bound measurement changed: " + name)
    completion = report["measurements"]["measure_completion"]["value"]
    if not completion.get("left_of_center_frames"):
        raise ValueError("left-of-center pass never measured")
    passed = completion.get("pass_and_return_frame") is not None
    if passed == case_id.endswith("incomplete_pass"):
        raise ValueError("measured passing completion differs from exact case")
    if not diagnostic_protocol:
        physical = result.get("physical_checks", {})
        if physical.get("setup", {}).get("status") != "met" or physical.get("attempt", {}).get("status") != "met":
            raise ValueError("original physical setup or motion unconfirmed")
    decoded = {}
    output.parent.mkdir(parents=True, exist_ok=True)
    for name in CAMERAS:
        video = attempt / (name + ".mkv")
        if not video.is_file():
            raise ValueError("original camera missing: " + name)
        receipt = output.with_name(output.stem + "-decode-" + name + ".json")
        decoded[name] = decode(video, len(mapping), mapping_sha256=sha(attempt / "video_frames.jsonl"), receipt=receipt)
    if not diagnostic_protocol:
        pixel = read(attempt / "pixel-review.json")
        if pixel.get("case_id") != case_id or pixel.get("reviewer") in (None, "") or pixel.get("actual_pixels_visible") is not True or pixel.get("physical_completion_reviewed") is not True:
            raise ValueError("independent actual-pixel and physical review missing")
        if pixel.get("video_sha256") != {name:sha(attempt / (name + ".mkv")) for name in CAMERAS}:
            raise ValueError("pixel review references different original footage")
    audit_record = {"format":"worker-delivery-audit-diagnostic" if diagnostic_protocol else "worker-delivery-audit",
                    "case_id":case_id,"original_frames":len(mapping),
                    "original_source_sha256":{name:sha(attempt / name) for name in required},
                    "decoded_video_sha256":{name:item["video_sha256"] for name,item in decoded.items()},
                    "checks":["native_source","all_participants","time_join","full_video_decode",
                              "physical_completion"],
                    "actual_pixels_reviewed":not diagnostic_protocol,
                    "physical_acceptance_claimed":False,"legal_judgment":"unresolved"}
    output.write_text(json.dumps(audit_record, indent=2) + "\n")
    return audit_record


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--diagnostic-protocol", action="store_true")
    args = parser.parse_args()
    result = audit(args.attempt,args.case,args.output,diagnostic_protocol=args.diagnostic_protocol)
    print(json.dumps({"case_id":result["case_id"],"frames":result["original_frames"],
                      "physical_acceptance_claimed":False},sort_keys=True))


if __name__ == "__main__":main()
